// Workflow F — Printful Product Listener
// Écoute product_synced, product_updated, product_deleted
// Met à jour totehm_cloth_support automatiquement

const cfg = $('⚙️ CONFIG').first().json;
const body = $input.first().json.body;
const type = body.type;
const sbh = {
  apikey: cfg.SB_KEY,
  Authorization: `Bearer ${cfg.SB_KEY}`,
  'Content-Type': 'application/json'
};

// product_deleted → passer active=false
if (type === 'product_deleted') {
  const pf_id = body.data?.sync_product?.id;
  if (!pf_id) return [{ json: { ok: true, action: 'ignored', reason: 'no product id' } }];
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_cloth_support?printful_product_id=eq.${pf_id}`,
    headers: sbh, json: true,
    body: { active: false }
  });
  return [{ json: { ok: true, action: 'deactivated', printful_product_id: pf_id } }];
}

// product_synced / product_updated → fetch détails + upsert
if (!['product_synced', 'product_updated'].includes(type)) {
  return [{ json: { ok: true, action: 'ignored', type } }];
}

const pf_id = body.data?.sync_product?.id;
if (!pf_id) return [{ json: { ok: true, action: 'ignored', reason: 'no product id' } }];

// 1. Récupérer les détails complets du produit depuis Printful
const pfRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.printful.com/store/products/${pf_id}`,
  headers: { Authorization: `Bearer ${cfg.PRINTFUL_TOKEN}` },
  json: true
});

const product = pfRes.result.sync_product;
const variants = pfRes.result.sync_variants;

// 2. Construire printful_variant_map
// { "S": { variant_id, sync_variant_id, retail_price }, ... }
const variantMap = {};
for (const v of variants) {
  if (!v.size) continue;
  variantMap[v.size] = {
    variant_id: v.variant_id,
    sync_variant_id: v.id,
    retail_price: parseFloat(v.retail_price)
  };
}

// 3. Vérifier si le support existe déjà en base
const existing = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_cloth_support?printful_product_id=eq.${pf_id}&select=id,price,max_pieces,active,print_area`,
  headers: sbh, json: true
});

const exists = existing && existing.length > 0;

// 4. Champs à upsert — NE PAS écraser : price, max_pieces, active, print_area, position
// Ces champs sont des décisions de marque, pas des données Printful
const upsertData = {
  printful_product_id: pf_id,
  printful_variant_map: variantMap,
  title: product.name,
  thumbnail_url: product.thumbnail_url || null
};

// Si nouveau produit → initialiser les champs de marque avec des valeurs par défaut
if (!exists) {
  upsertData.price = 0;        // à remplir par Wah
  upsertData.max_pieces = 0;  // à remplir par Wah
  upsertData.active = false;   // inactif jusqu'à configuration
  upsertData.claimed = 0;
  upsertData.print_area = {
    method: 'dtg',
    placement: 'back',
    width_in: 12,
    height_in: 16,
    dpi: 300
  };
}

// 5. Upsert dans totehm_cloth_support
const method = exists ? 'PATCH' : 'POST';
const url = exists
  ? `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_cloth_support?printful_product_id=eq.${pf_id}`
  : 'https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_cloth_support';

await this.helpers.httpRequest({
  method, url, headers: { ...sbh, Prefer: 'return=representation' },
  body: upsertData, json: true
});

return [{ json: {
  ok: true,
  action: exists ? 'updated' : 'created',
  printful_product_id: pf_id,
  title: product.name,
  sizes: Object.keys(variantMap)
} }];
